import{_ as t,H as a,f as r,i as p}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"春节策划（一） | 视频课内容精选：Web渗透测试工具教学","description":"","frontmatter":{},"headers":[{"level":2,"title":"第一节","slug":"第一节","link":"#第一节","children":[]},{"level":2,"title":"第二节","slug":"第二节","link":"#第二节","children":[]},{"level":2,"title":"第三节","slug":"第三节","link":"#第三节","children":[]}],"relativePath":"Web漏洞挖掘实战/春节策划（一）｜视频课内容精选：Web渗透测试工具教学.md","filePath":"Web漏洞挖掘实战/春节策划（一）｜视频课内容精选：Web渗透测试工具教学.md","lastUpdated":1795536081000}'),i={name:"Web漏洞挖掘实战/春节策划（一）｜视频课内容精选：Web渗透测试工具教学.md"};function l(n,e,o,s,E,h){return a(),r("div",null,[...e[0]||(e[0]=[p('<h1 id="春节策划-一-视频课内容精选-web渗透测试工具教学" tabindex="-1">春节策划（一） | 视频课内容精选：Web渗透测试工具教学 <a class="header-anchor" href="#春节策划-一-视频课内容精选-web渗透测试工具教学" aria-label="Permalink to &quot;春节策划（一） | 视频课内容精选：Web渗透测试工具教学&quot;">​</a></h1><p>你好，我是王昊天。</p><p>今天是除夕，首先祝你新年快乐，希望你在新的一年收获满满！</p><p>在这个特别的节日，我要送给你一套 Web 安全基础的教学视频作为新年礼物。在之前的课程中，我们已经深入学习了 Web 漏洞挖掘的“失效的访问控制”“加密失败”“注入”“不安全的设计”的内容。</p><p>为了加深你对这部分内容的理解和掌握程度，我特地从我第一季的视频课程《Web 安全攻防实战》中精选了 3 讲视频内容，提供给你学习。</p><h2 id="第一节" tabindex="-1">第一节 <a class="header-anchor" href="#第一节" aria-label="Permalink to &quot;第一节&quot;">​</a></h2><p>08 | 常见的 Web 安全漏洞都有哪些？</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/%25E6%2598%25A5%25E8%258A%2582%25E7%25AD%2596%25E5%2588%2592%25EF%25BC%2588%25E4%25B8%2580%25EF%25BC%2589/1.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/%25E6%2598%25A5%25E8%258A%2582%25E7%25AD%2596%25E5%2588%2592%25EF%25BC%2588%25E4%25B8%2580%25EF%25BC%2589/1.jpeg" alt=""></a></p><p>在这一节视频课程中，我们会对 Web 应用使用的 HTTP 协议进行学习，然后结合 Web 安全攻防要点分析 Web 安全的本质。目的是，帮助你更好地理解和掌握 Web 安全。</p><h2 id="第二节" tabindex="-1">第二节 <a class="header-anchor" href="#第二节" aria-label="Permalink to &quot;第二节&quot;">​</a></h2><p>09 | Web 渗透工具入门：Burp Suite、cURL、Postman</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/%25E6%2598%25A5%25E8%258A%2582%25E7%25AD%2596%25E5%2588%2592%25EF%25BC%2588%25E4%25B8%2580%25EF%25BC%2589/2.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/%25E6%2598%25A5%25E8%258A%2582%25E7%25AD%2596%25E5%2588%2592%25EF%25BC%2588%25E4%25B8%2580%25EF%25BC%2589/2.jpeg" alt=""></a></p><p>在这一节视频课程中，我们会对 Web 安全领域的常用工具进行学习，主要包括 Burp Suite、cURL 和 Postman。</p><p>这一讲视频中用到的插件安装地址，我也一起提供给你。</p><ol><li><p>cURL 的插件安装地址：<a href="https://curl.haxx.se/" target="_blank" rel="noreferrer">https://curl.haxx.se/</a></p></li><li><p>cURL 下载地址：<a href="https://curl.haxx.se/download.html" target="_blank" rel="noreferrer">https://curl.haxx.se/download.html</a></p></li><li><p>Burp Suite 插件安装地址：<a href="https://portswigger.net/burp" target="_blank" rel="noreferrer">https://portswigger.net/burp</a></p></li><li><p>Burp Suite 下载地址：<a href="https://portswigger.net/burp/communitydownload" target="_blank" rel="noreferrer">https://portswigger.net/burp/communitydownload</a></p></li><li><p>Postman 插件安装地址：<a href="https://www.postman.com/" target="_blank" rel="noreferrer">https://www.postman.com/</a></p></li><li><p>Postman 下载地址：<a href="https://www.postman.com/downloads/" target="_blank" rel="noreferrer">https://www.postman.com/downloads/</a></p></li></ol><p>这样，在《Web 漏洞挖掘实战》这门课之后的学习中，你就可以用这些工具来进行实战测试了。</p><h2 id="第三节" tabindex="-1">第三节 <a class="header-anchor" href="#第三节" aria-label="Permalink to &quot;第三节&quot;">​</a></h2><p>10 | Web 渗透插件入门：Wappalyzer、HackBar</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/%25E6%2598%25A5%25E8%258A%2582%25E7%25AD%2596%25E5%2588%2592%25EF%25BC%2588%25E4%25B8%2580%25EF%25BC%2589/3.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/%25E6%2598%25A5%25E8%258A%2582%25E7%25AD%2596%25E5%2588%2592%25EF%25BC%2588%25E4%25B8%2580%25EF%25BC%2589/3.jpeg" alt=""></a></p><p>在这节视频课程中，我们会对 Web 渗透插件进行学习，主要包括 Wappalyzer 和 HackBar。掌握了这两个插件，可以对我们的漏洞挖掘过程提供极大的帮助。</p><p>这一讲视频中用到的插件安装地址，我也一起提供给你。</p><ol><li><p>HackBar 插件安装地址：<a href="https://addons.mozilla.org/en-US/firefox/addon/hackbar-quantum/" target="_blank" rel="noreferrer">https://addons.mozilla.org/en-US/firefox/addon/hackbar-quantum/</a></p></li><li><p>Wappalyzer 插件安装地址：<a href="https://www.wappalyzer.com/" target="_blank" rel="noreferrer">https://www.wappalyzer.com/</a></p></li></ol><p>以上就是我要送给你的 3 讲视频内容。我再概括下这三节课程的内容，你可以进行针对性地学习：</p><ul><li><p>第一节课从 HTTP 协议的角度，帮助你理解基本的 Web 应用系统通信原理；</p></li><li><p>第二节课从 HTTP 协议操纵工具入手，帮助你在 Web 领域行走自如；</p></li><li><p>第三节课则从自动化插件的领域，帮助你快速识别目标 Web 应用架构。</p></li></ul><p>其实，抽选这三讲内容，我的主要考量是：在《Web 漏洞挖掘实战》这门课中，我一直致力于讲解 Web 领域的漏洞挖掘和利用思维，以及从防御的视角去看开发，所以其中涉及的渗透实践类的讲解并不多。</p><p>但在我看来，无论是尝试去做 Web 领域的漏洞挖掘，还是尝试手工复现及利用我们所讲解的漏洞，掌握 Web 领域的渗透测试工具都是必不可少的。凭借这些优秀的工具，可以大幅提高我们学习和实践的效率，也可以加深我们对专栏内容的理解。</p><p>今天的福利就到这里，相信这 3 讲视频内容，可以帮助你拥有快速在 Web 安全领域上手的能力。</p>',27)])])}const u=t(i,[["render",l]]);export{c as __pageData,u as default};
